  ui_story_5059_50590103_73_dialog_content = "Tessa me ajudou a fazer isso...",
  ui_story_5059_50590103_74_dialog_content = "Sim, foi minha primeira vez fazendo pirulitos naquela forma.",
  ui_story_5059_50590103_75_dialog_content = "Foi um pouco demorado, mas Kanna me implorou.",
  ui_story_5059_50590103_76_dialog_content = "Você consegue até fazer pirulitos? Estou devidamente impressionado.",
  ui_story_5059_50590103_77_dialog_content = "Eu quero te dar um, PlayerName...",
  ui_story_5059_50590103_78_dialog_content = "Para mim? Tem certeza?",
  ui_story_5059_50590103_79_dialog_content = "Sim... PlayerName é um cara legal.",
  ui_story_5059_50590103_80_dialog_content = "Obrigado, vou cuidar bem!",
  ui_story_5059_50590103_81_dialog_content = "Vamos rastrear a Senhora Elma. Eu vou ajudar.",
  ui_story_5059_50590103_82_dialog_content = "Burro PlayerName.",
  ui_story_5059_50590103_83_dialog_content = "Um cara mau que não se importa comigo.",
  ui_story_5059_50590103_84_dialog_content = "Não posso fazer isso, PlayerName. Kanna está em uma idade em que precisa de amor e cuidado carinhoso.",
  ui_story_5059_50590103_85_dialog_content = "1, \nand and, PlayerName...\n, and image the ( 13 parts the prere, PlayerName (lock, PlayerName.\nTranslation:Você está​ 1",
  ui_story_5059_50590103_86_dialog_content = "Desculpe, desculpe! Peço desculpas a todos.",
  ui_story_5059_50590103_87_dialog_content = "Me dê outra chance, por favor! Vou tomar a decisão certa desta vez!",
  ui_story_5059_50590104_1_dialog_content = "Não!",
  ui_story_5059_50590104_2_dialog_content = "Ei, é aquele Vice?",
  ui_story_5059_50590104_3_dialog_content = "Vamos conferir.",
  ui_story_5059_50590104_4_dialog_content = "Não vou deixar você vender coisas tão estranhas para os amigos de PlayerName.",
  ui_story_5059_50590104_5_dialog_content = "Mas senhorita Vice, essa jovem está muito interessada nos meus produtos.",
  ui_story_5059_50590104_6_dialog_content = "Veja, este é o novo produto do exclusivo confeiteiro dos prestigiosos nobres de Lumópolis.",
  ui_story_5059_50590104_7_dialog_content = "Esta última linha de sobremesas sortidas aleatoriamente está disponível apenas nesta semana!",
  ui_story_5059_50590104_8_dialog_content = "Como aquele comerciante estranho conseguiu se envolver com Elma novamente?",
  ui_story_5059_50590104_9_dialog_content = "Talvez ela tenha a habilidade de atrair vendedores?",
  ui_story_5059_50590104_10_dialog_content = "Ela realmente parece ser do tipo que se deixa convencer a comprar coisas facilmente.",
  ui_story_5059_50590104_11_dialog_content = "Esta caixa de sobremesas aleatórias parece atraente.",
  ui_story_5059_50590104_12_dialog_content = "Eu sabia que você tem bom gosto! Veja, Srta. Vice, ela está muito interessada.",
  ui_story_5059_50590104_13_dialog_content = "Ainda é um \"Não!\" Você a enganou com seu discurso.",
  ui_story_5059_50590104_14_dialog_content = "De jeito nenhum. Os negócios sempre foram sobre valor justo e garantir que todos obtenham o que precisam.",
  ui_story_5059_50590104_15_dialog_content = "Mas não com caixas surpresa de sobremesa! Você está sendo desrespeitoso com a comida!",
  ui_story_5059_50590104_16_dialog_content = "Por fornecer sobremesa e a emoção da loteria ao mesmo tempo, você deveria me chamar de gênio do marketing, Senhorita Vice.",
  ui_story_5059_50590104_17_dialog_content = "Deixe-me mostrar-lhe outra série de caixas surpresas de sobremesas, senhora.",
  ui_story_5059_50590104_18_dialog_content = "Não é uma oferta limitada, mas apresenta um prato secreto que só alguém que o experimentar descobrirá o que é.",
  ui_story_5059_50590104_19_dialog_content = "O quê, uma sobremesa secreta?",
  ui_story_5059_50590104_20_dialog_content = "Jomu!",
  ui_story_5059_50590104_21_dialog_content = "Ah, ei, lá está você, chefe.",
  ui_story_5059_50590104_22_dialog_content = "Você está importunando as pessoas com coisas estranhas de novo?",
  ui_story_5059_50590104_23_dialog_content = "Você está errado, chefe. Eu e essa senhora nos demos muito bem. Você não pode chamar isso de assédio.",
  ui_story_5059_50590104_24_dialog_content = "Mesmo...",
  ui_story_5059_50590104_25_dialog_content = "Claro. Você pode testar nossa amizade de qualquer maneira, a qualquer hora.",
  ui_story_5059_50590104_26_dialog_content = "Tenho a coisa exata para isso. Se você passar no Desafio de Rapport 4, acreditarei que não estava importunando Elma.",
  ui_story_5059_50590104_27_dialog_content = "Mas, por outro lado, se você estragar tudo... Você terá que dar todas as caixas surpresa para ela como compensação.",
  ui_story_5059_50590104_28_dialog_content = "Bem, mesmo que isso não pareça justo...",
  ui_story_5059_50590104_29_dialog_content = "O prêmio com certeza vale a pena! Vamos começar agora!",
  ui_story_5059_50590104_30_dialog_content = "Elma realmente gosta muito de Tohru?",
  ui_story_5059_50590104_31_dialog_content = "Sim.",
  ui_story_5059_50590104_32_dialog_content = "Por que começar com uma pergunta tão direta?",
  ui_story_5059_50590104_33_dialog_content = "Ahem... Não é possível que eu goste de Tohru... É só que nos conhecemos há muito tempo, só isso.",
  ui_story_5059_50590104_34_dialog_content = "Eu só gosto de treinar com ela. Acho que ela está destinada a ser minha némesis!",
  ui_story_5059_50590104_35_dialog_content = "Então, por que você escolheu essa resposta?",
  ui_story_5059_50590104_36_dialog_content = ":O qu.",
  ui_story_5059_50590104_37_dialog_content = "É sua culpa por não me mostrar como usar isso corretamente!",
  ui_story_5059_50590104_38_dialog_content = "Essa tentativa de encobrir foi óbvia demais, Elma...",
  ui_story_5059_50590104_39_dialog_content = "Ah... Próxima pergunta, agora!",
  ui_story_5059_50590104_40_dialog_content = "Não.",
  ui_story_5059_50590104_41_dialog_content = "Por que começar com uma pergunta tão direta?",
  ui_story_5059_50590104_42_dialog_content = "Não é possível que eu goste de Tohru!",
  ui_story_5059_50590104_43_dialog_content = "Então por que você escolheu a outra resposta?",
  ui_story_5059_50590104_44_dialog_content = "Ah... Bem, eu não queria dar uma vitória fácil a um mero Celestita!",
  ui_story_5059_50590104_45_dialog_content = "Então... Elma gosta ou não gosta de Tohru?",
  ui_story_5059_50590104_46_dialog_content = "Não está claro como o dia?",
  ui_story_5059_50590104_47_dialog_content = "Claro que ela...",
  ui_story_5059_50590104_48_dialog_content = "Pare! Vou comprar as caixas!",
  ui_story_5059_50590104_49_dialog_content = "O que é necessário para Elma participar de uma batalha dentro da facção Caos?",
  ui_story_5059_50590104_50_dialog_content = "Bolo de chocolate tamanho super",
  ui_story_5059_50590104_51_dialog_content = "Então, apenas um bolo de chocolate superdimensionado não seria suficiente?",
  ui_story_5059_50590104_52_dialog_content = "Claro que não. É perigoso se envolver em uma luta entre duas facções.",
  ui_story_5059_50590104_53_dialog_content = "Sem mencionar que é apenas um bolo superdimensionado... Você acha que nós, dragões, não temos orgulho?",
  ui_story_5059_50590104_54_dialog_content = "E se fosse um ainda maior?",
  ui_story_5059_50590104_55_dialog_content = "Se fosse grande o suficiente para que eu não conseguisse terminar nem mesmo em forma de dragão, eu consideraria!",
  ui_story_5059_50590104_56_dialog_content = "Todos os doces que ela pode comer",
  ui_story_5059_50590104_57_dialog_content = "Eu prefiro o tipo feito pelos chefs do palácio.",
  ui_story_5059_50590104_58_dialog_content = "Eu já comi antes e ainda me lembro do quão gostosos eram.",
  ui_story_5059_50590104_59_dialog_content = "Posso garantir que os itens nas minhas caixas surpresa são tão bons quanto qualquer coisa que você já teve.",
  ui_story_5059_50590104_60_dialog_content = ",",
  ui_story_5059_50590104_61_dialog_content = "Muito menos colocá-lo sorrateiramente durante um jogo como um anúncio.",
  ui_story_5059_50590104_62_dialog_content = "Bem, na verdade, eu tenho aprendido a fazer sobremesas.",
  ui_story_5059_50590104_63_dialog_content = "...",
  ui_story_5059_50590104_64_dialog_content = "Por que você ficou quieto de repente?!",
  ui_story_5059_50590104_65_dialog_content = "Você já desafiou Tohru para ver de quem é a cauda mais longa?",
  ui_story_5059_50590104_66_dialog_content = "Sim.",
  ui_story_5059_50590104_67_dialog_content = "Tá bom, quem inventou essa pergunta?",
  ui_story_5059_50590104_68_dialog_content = "Tohru provavelmente ainda se lembra de curiosidades assim...",
  ui_story_5059_50590104_69_dialog_content = "Bem, a pergunta foi realmente de Tohru.",
  ui_story_5059_50590104_70_dialog_content = "Ela deve te ver como um amigo para guardar tantos pequenos detalhes em mente.",
  ui_story_5059_50590104_71_dialog_content = "O que você quer dizer? Tenho certeza de que isso é porque ela nunca poderia esquecer os desafios que teve contra um dragão poderoso como eu!",
  ui_story_5059_50590104_72_dialog_content = "Não.",
  ui_story_5059_50590104_73_dialog_content = "Então isso é mesmo um \"desafio\"?",
  ui_story_5059_50590104_74_dialog_content = "Sim. Eu estava interessado em desafiar Tohru para todos os tipos de coisas por um período de tempo.",
  ui_story_5059_50590104_75_dialog_content = "Isso parece que você estava tentando chamar a atenção dela.",
  ui_story_5059_50590104_76_dialog_content = "Vocês dois são unidos.",
  ui_story_5059_50590104_77_dialog_content = "Gostaria de encomendar um bolo personalizado para simbolizar sua amizade então?",
  ui_story_5059_50590104_78_dialog_content = "Não!",
  ui_story_5059_50590104_79_dialog_content = "Você não acertou todos, Jomu.",
  ui_story_5059_50590104_80_dialog_content = "Você é a pessoa melhor. Admito a derrota, chefe.",
  ui_story_5059_50590104_81_dialog_content = "Estou envergonhado por não ter feito o suficiente para conhecer meu cliente...",
  ui_story_5059_50590104_82_dialog_content = "Nunca subestime o vínculo entre aqueles que se aventuraram e lutaram juntos, Jomu.",
  ui_story_5059_50590104_83_dialog_content = "Isso não é algo que você pode obter apenas observando e ouvindo boatos.",
  ui_story_5059_50590104_84_dialog_content = "Eu não imaginava que você soubesse tanto sobre mim, PlayerName. Há algo que você gostaria da minha ajuda?",
  ui_story_5059_50590104_85_dialog_content = "Agradeço a oferta, mas acredito que você também tem muito o que fazer.",
  ui_story_5059_50590104_86_dialog_content = "Vocês mortais realmente levam uma vida agitada.",
  ui_story_5059_50590104_87_dialog_content = "Não se preocupe, temos a capacidade de lidar com o que acontece no nosso mundo.",
  ui_story_5059_50590104_88_dialog_content = "Certo, Vice?",
  ui_story_5059_50590104_89_dialog_content = "Vice...? Onde ela foi?",
  ui_story_5059_50590104_90_dialog_content = "Espere, que cheiro é esse? Tão forte...",
  ui_story_5059_50590104_91_dialog_content = "PlayerName! Elma!",
  ui_story_5059_50590104_92_dialog_content = "Fiz um bolo...!",
  ui_story_5059_50590104_93_dialog_content = "Corra, Elma!",
  ui_story_5059_50590104_94_dialog_content = [[
