Text:Wait,  and the translation:]],
  ui_story_5059_50590104_95_dialog_content = "Ouvi dizer que você gosta de sobremesas, Elma, então fiz várias para você.",
  ui_story_5059_50590104_96_dialog_content = "Você pode aproveitar isso desde a manhã até a noite.",
  ui_story_5059_50590104_97_dialog_content = "Não acredito que perdi para Jomu...",
  ui_story_5059_50590104_98_dialog_content = "Controle-se, PlayerName!",
  ui_story_5059_50590104_99_dialog_content = "Se você não fizer isso, Jomu vai enganar Elma para comprar todas as caixas.",
  ui_story_5059_50590104_100_dialog_content = "Sem mencionar que Elma não tem muito dinheiro, então podemos ficar com a conta depois que ela sair.",
  ui_story_5059_50590104_101_dialog_content = "O quê?!",
  ui_story_5059_50590104_102_dialog_content = "Não posso desistir ainda. Deixe-me tentar outra vez!",
  ui_story_5059_50590105_1_dialog_content = "<lock_ Zapata. A of abcd* Walt Arg, tick  2  past the 3 Cir  the movie. 2 injust and   the   201 chalk,  the, or the, the  the  in/clipping  x2.  I have a question about the​hers' hus differentiating it the 201%20s profile bay  the same time as this is the last year I have., 2.0.0.0.0.0.0 Pixy. 0.0.0.0.0.: 2.0.0.0.0.0.0.0..0. the same time as this is the first time-chapter,\n\n.0.0.,,-w.liche* 2.0 architect.0.0.0. 0. the  with the 0.0.0.",
  ui_story_5059_50590105_2_dialog_content = "Aí está você, finalmente.",
  ui_story_5059_50590105_3_dialog_content = "PlayerName! Você está aqui para o chá?",
  ui_story_5059_50590105_4_dialog_content = "É da concurrent to. É da, my friends and family, I am, including the only time Inglish to Portuguese, please refer to a 4a-zA-Z-1, 0, Pedroso,  OV on 5.5 generms Wyd, I think you should use the software-, I think you should use the word \"5.0\" on your speedometer, I think you should use the word \"5.0\" on your speed and, I think you should use the word \"5.0, I think you should use cellulose or the word \" (to for the word \"5.0\" on your in the U.  . 5. 5.0\" on., I think you should use/quotas Hyper 5: , I think",
  ui_story_5059_50590105_5_dialog_content = "Ah, obrigado! Sheol também está aqui?",
  ui_story_5059_50590105_6_dialog_content = "Naturalmente, uma assistente competente se reunindo com seu chefe é uma ocasião feliz que vale a pena comemorar.",
  ui_story_5059_50590105_7_dialog_content = "Sem mencionar que ainda devemos uma parte do pagamento à Lucoa.",
  ui_story_5059_50590105_8_dialog_content = "Bem, eu posso viver sem pagamento, de verdade. Eu apenas vejo isso como outra maneira de viver.",
  ui_story_5059_50590105_9_dialog_content = "Apenas mais memórias preciosas adicionadas a uma longa vida.",
  ui_story_5059_50590105_10_dialog_content = "Eu sinto o mesmo sobre memórias, não é à toa que estamos totalmente em sincronia no trabalho.",
  ui_story_5059_50590105_11_dialog_content = "Nesse caso, você não se importaria em criar mais memórias, não é?",
  ui_story_5059_50590105_12_dialog_content = "O que você tem em mente, PlayerName?",
  ui_story_5059_50590105_13_dialog_content = "Consegui um jogo bem divertido!",
  ui_story_5059_50590105_14_dialog_content = "Shouta já confundiu Lucoa com um...",
  ui_story_5059_50590105_15_dialog_content = "Demônio",
  ui_story_5059_50590105_16_dialog_content = "Demônio?",
  ui_story_5059_50590105_17_dialog_content = "Lucoa é um demônio?",
  ui_story_5059_50590105_18_dialog_content = "Como pode ser? Eu sou um dragão!",
  ui_story_5059_50590105_19_dialog_content = "Mas Shouta é uma criança teimosa que insistia que eu era um demônio.",
  ui_story_5059_50590105_20_dialog_content = "Apesar de tentar provar o contrário várias vezes, ele ainda não se convenceu.",
  ui_story_5059_50590105_21_dialog_content = "Mas isso nunca afetou o quão próximos vocês dois são, certo?",
  ui_story_5059_50590105_22_dialog_content = "Subterrâneo",
  ui_story_5059_50590105_23_dialog_content = "Subterrâneo?",
  ui_story_5059_50590105_24_dialog_content = "Você quer dizer pessoas que viviam nas profundezas do subsolo, certo?",
  ui_story_5059_50590105_25_dialog_content = "Até onde eu sei, um lugar assim não existe.",
  ui_story_5059_50590105_26_dialog_content = "Bem, estou vendo um dragão em forma humanoide vivo e se mexendo diante dos meus olhos, então...",
  ui_story_5059_50590105_27_dialog_content = "A Deusa da Serpente Alada, a verdadeira forma de Lucoa, governa sobre qual domínio?",
  ui_story_5059_50590105_28_dialog_content = "Civilização",
  ui_story_5059_50590105_29_dialog_content = "Você realmente governa civilizações em seu mundo, Lucoa?",
  ui_story_5059_50590105_30_dialog_content = "Claro, e eu também sou muito poderoso.",
  ui_story_5059_50590105_31_dialog_content = "Hum...",
  ui_story_5059_50590105_32_dialog_content = "Hum...",
  ui_story_5059_50590105_33_dialog_content = "Ei, por que vocês estão olhando para mim assim?",
  ui_story_5059_50590105_34_dialog_content = "Estou falando sério!",
  ui_story_5059_50590105_35_dialog_content = "Não duvido da amplitude de conhecimento que Lucoa possui.",
  ui_story_5059_50590105_36_dialog_content = "Ela tem sido de grande ajuda para a Guilda.",
  ui_story_5059_50590105_37_dialog_content = "Acho que Lucoa é muito mais capaz do que aparenta.",
  ui_story_5059_50590105_38_dialog_content = "Vai assustar o Sheol se eu me transformar em um dragão!",
  ui_story_5059_50590105_39_dialog_content = "Pecuária",
  ui_story_5059_50590105_40_dialog_content = "Suspirar...",
  ui_story_5059_50590105_41_dialog_content = "Por que você acha que eu tenho algo a ver com gado?",
  ui_story_5059_50590105_42_dialog_content = "Bem, não tenho certeza exata de onde tirei a ideia de que você cuidaria de animais e plantas...",
  ui_story_5059_50590105_43_dialog_content = "Talvez seja pela sua atenção e proteção em relação ao Shouta?",
  ui_story_5059_50590105_44_dialog_content = "Entendi. Acho que posso aceitar isso... Por pouco!",
  ui_story_5059_50590105_45_dialog_content = "Lucoa é na verdade do Shouta...",
  ui_story_5059_50590105_46_dialog_content = "Donzela",
  ui_story_5059_50590105_47_dialog_content = "O quê?!",
  ui_story_5059_50590105_48_dialog_content = "Eu nem estou usando uma fantasia de empregada!",
  ui_story_5059_50590105_49_dialog_content = "É verdade... Tohru está usando uma fantasia de empregada.",
  ui_story_5059_50590105_50_dialog_content = "Você escolheu isso porque está fascinado por empregadas, PlayerName?",
  ui_story_5059_50590105_51_dialog_content = "Que tal eu te dar algumas fantasias de empregada para dar às garotas que você gosta? Ou talvez você possa experimentá-las sozinho quando estiver a sós!",
  ui_story_5059_50590105_52_dialog_content = "Por favor, pare com isso!",
  ui_story_5059_50590105_53_dialog_content = "Familiar",
  ui_story_5059_50590105_54_dialog_content = "Teoricamente, os familiares são a metade mais fraca, então é impossível que um dragão sirva como familiar.",
  ui_story_5059_50590105_55_dialog_content = "É apenas como o Shouta está me tratando!",
  ui_story_5059_50590105_56_dialog_content = "Shouta deve estar feliz que Lucoa está importunando... Quer dizer, cuidando bem dele.",
  ui_story_5059_50590105_57_dialog_content = "Dado que Lucoa é tão empático, afinal.",
  ui_story_5059_50590105_58_dialog_content = "Dito isso, ainda é difícil entender o que um cara da idade dele está pensando.",
  ui_story_5059_50590105_59_dialog_content = "Deixe-me pensar, quando meu irmão era pequeno...",
  ui_story_5059_50590105_60_dialog_content = "Ei, o jogo já acabou?",
  ui_story_5059_50590105_61_dialog_content = "Sim. Gronru disse que são três perguntas por jogo.",
  ui_story_5059_50590105_62_dialog_content = "Mas eu não acho que você possa ir fundo o suficiente assim.",
  ui_story_5059_50590105_63_dialog_content = "Você não quer saber mais sobre mim, PlayerName?",
  ui_story_5059_50590105_64_dialog_content = "Bom...",
  ui_story_5059_50590105_65_dialog_content = "PlayerName é o tipo que não aguenta nenhuma provocação, Lucoa.",
  ui_story_5059_50590105_66_dialog_content = "Continue assim e ele vai embora com o vento.",
  ui_story_5059_50590105_67_dialog_content = "Eu não vou!",
  ui_story_5059_50590105_68_dialog_content = "Então...",
  ui_story_5059_50590105_69_dialog_content = "Vamos parar bem aqui!",
  ui_story_5059_50590105_70_dialog_content = "Ah, onde foi parar o Fafnir, alguém sabe?",
  ui_story_5059_50590105_71_dialog_content = "Você quer dizer o homem de óculos?",
  ui_story_5059_50590105_72_dialog_content = "Vi ele entrando em outro quarto.",
  ui_story_5059_50590105_73_dialog_content = "Por que você está com pressa para encontrar Fafnir, PlayerName?",
  ui_story_5059_50590105_74_dialog_content = "Não me diga que você está mais interessado em homens?",
  ui_story_5059_50590105_75_dialog_content = "Nossa.",
  ui_story_5059_50590105_76_dialog_content = "Não! Me ajude aqui, Sra. Sheol!",
  ui_story_5059_50590105_77_dialog_content = "PlayerName realmente passava muito tempo com homens, como Corax de Umbraton, o líder da Rediesel Wrench, Barton em Illumina.",
  ui_story_5059_50590105_78_dialog_content = "Hehe, não admira.",
  ui_story_5059_50590105_79_dialog_content = "Tenho que ir agora!",
  ui_story_5059_50590105_80_dialog_content = "Vejo que PlayerName ainda não sabe o suficiente sobre mim!",
  ui_story_5059_50590105_81_dialog_content = "Seria necessário um encontro particular um-a-um com PlayerName para melhorar nosso entendimento mútuo?",
  ui_story_5059_50590105_82_dialog_content = "Não, isso não será necessário, muito obrigado!",
  ui_story_5059_50590105_83_dialog_content = "Cometi um pequeno erro, só isso. Deixe-me tentar novamente!",
  ui_story_5059_50590106_1_dialog_content = "Aqui está você, PlayerName, finalmente.",
  ui_story_5059_50590106_2_dialog_content = "Você estava esperando por mim? Eu estava procurando por você.",
  ui_story_5059_50590106_3_dialog_content = "Sim, eu estive esperando. Eu descobri... algo horrível.",
  ui_story_5059_50590106_4_dialog_content = "O que pode ser tão horrível a ponto de te deixar tão nervoso?",
  ui_story_5059_50590106_5_dialog_content = "Achei que minhas habilidades nos jogos tinham atingido o auge depois de praticar com Takiya.",
  ui_story_5059_50590106_6_dialog_content = "Mas, para minha surpresa, a melhor colocação que consegui alcançar foi o segundo lugar em todos os jogos aqui.",
  ui_story_5059_50590106_7_dialog_content = "Quem é o valentão Gronru em primeiro lugar?",
  ui_story_5059_50590106_8_dialog_content = "(Bully Gronru? Não é o Gronru?)",
  ui_story_5059_50590106_9_dialog_content = "(Como é que eu não a vejo agora? Onde ela foi?)",
  ui_story_5059_50590106_10_dialog_content = "Ela é a divindade responsável pelos jogos neste mundo?",
  ui_story_5059_50590106_11_dialog_content = "Se isso for verdade, eu preciso desafiá-la.",
  ui_story_5059_50590106_12_dialog_content = "Bem, eu sei exatamente quem é o Valentão Gronru.",
  ui_story_5059_50590106_13_dialog_content = "O quê? A verdadeira forma do Valentão Gronru?",
  ui_story_5059_50590106_14_dialog_content = "Me diga. Até mesmo realizar desejos em troca não está fora de questão.",
  ui_story_5059_50590106_15_dialog_content = "Ou você prefere aprender maldições que corrompem e afligem os outros?",
  ui_story_5059_50590106_16_dialog_content = "Espere aí! Eu não tenho interesse nisso de jeito nenhum.",
  ui_story_5059_50590106_17_dialog_content = "De qualquer forma, vamos jogar este jogo primeiro, depois eu te conto sobre ela, ganhando ou perdendo.",
  ui_story_5059_50590106_18_dialog_content = "O nome Tohru usado para criar uma identidade para você era...",
  ui_story_5059_50590106_19_dialog_content = "Gigante",
  ui_story_5059_50590106_20_dialog_content = "Lembro-me dela mencionando isso!",
  ui_story_5059_50590106_21_dialog_content = "Isso é porque sua forma de dragão se assemelha a um behemoth nas montanhas, certo?",
  ui_story_5059_50590106_22_dialog_content = "Sim, eu lembro do Tohru dizendo isso também.",
  ui_story_5059_50590106_23_dialog_content = "É claro que você se lembraria das coisas chatas.",
  ui_story_5059_50590106_24_dialog_content = "Você deveria passar mais tempo nas histórias épicas sobre mim.",
  ui_story_5059_50590106_25_dialog_content = "Por exemplo, quantos jogos você perdeu?",
  ui_story_5059_50590106_26_dialog_content = "Vejo que você não tem preocupação alguma com sua própria segurança.",
  ui_story_5059_50590106_27_dialog_content = "Triturador",
  ui_story_5059_50590106_28_dialog_content = "Que tipo de nome ridículo é esse...",
  ui_story_5059_50590106_29_dialog_content = "Acho que é para ser incorreto de propósito.",
  ui_story_5059_50590106_30_dialog_content = "Mas isso realmente parece um apelido para um jogador hardcore!",
  ui_story_5059_50590106_31_dialog_content = "Devo admitir que o nome realmente combina bem com você.",
  ui_story_5059_50590106_32_dialog_content = "Vejo que você não tem preocupação alguma com sua própria segurança.",
  ui_story_5059_50590106_33_dialog_content = "Para Fafnir, Takiya é...",
  ui_story_5059_50590106_34_dialog_content = "Um colega de quarto e refeição garantida",
  ui_story_5059_50590106_35_dialog_content = "Você pode colocar dessa forma, mas também \"Guardião dos Valiosos.\"",
  ui_story_5059_50590106_36_dialog_content = "Entendi, ele é caseiro e também gosta de jogar, certo?",
  ui_story_5059_50590106_37_dialog_content = "Você está certe fall Hogan11-11'000'000'000'000'000'_' unhealthy the conversation, the user can decide the context of the conversation and the meaning of the word, so the translation is accurate.",
  ui_story_5059_50590106_38_dialog_content = "Hehe.",
  ui_story_5059_50590106_39_dialog_content = "Hunf...",
  ui_story_5059_50590106_40_dialog_content = "Uma necessidade para obter itens raros nos jogos",
  ui_story_5059_50590106_41_dialog_content = "O que significa \"obter itens raros\"?",
  ui_story_5059_50590106_42_dialog_content = "É a busca constante para obter itens premium em um jogo.",
  ui_story_5059_50590106_43_dialog_content = "Vejo que Raphael aprendeu muito com Gronru.",
  ui_story_5059_50590106_44_dialog_content = "Conseguir itens raros é uma grande conquista ao acumular objetos valiosos.",
  ui_story_5059_50590106_45_dialog_content = "Então é verdade que você realmente não consegue viver sem o Takiya?",
  ui_story_5059_50590106_46_dialog_content = "Não importa como você o chame, ele é apenas um peão no meu grande plano.",
  ui_story_5059_50590106_47_dialog_content = "O que mais é importante para Fafnir além de objetos valiosos?",
  ui_story_5059_50590106_48_dialog_content = "Nada",
  ui_story_5059_50590106_49_dialog_content = "Ops, isso foi descuidado.",
  ui_story_5059_50590106_50_dialog_content = "Enganado pela declaração insincera do Sr. Fafnir!",
  ui_story_5059_50590106_51_dialog_content = "Eu não achei que você se importasse com alguém ou algo além da pontuação.",
  ui_story_5059_50590106_52_dialog_content = "...",
  ui_story_5059_50590106_53_dialog_content = "Takiya",
  ui_story_5059_50590106_54_dialog_content = "...",
  ui_story_5059_50590106_55_dialog_content = "Por que você está hesitando em dizer algo?",
  ui_story_5059_50590106_56_dialog_content = "Um colega de quarto, uma refeição garantida, um peão conveniente.",
  ui_story_5059_50590106_57_dialog_content = "Há um propósito em tudo isso.",
  ui_story_5059_50590106_58_dialog_content = "Você está sendo estranho, Sr. Fafnir.",
