  ui_story_5059_50590106_61_dialog_content = "...",
  ui_story_5059_50590106_62_dialog_content = "Eu não esperava isso de jeito nenhum.",
  ui_story_5059_50590106_63_dialog_content = "Como você sabe tanto sobre mim?",
  ui_story_5059_50590106_64_dialog_content = "Você está cobiçando meu tesouro?",
  ui_story_5059_50590106_65_dialog_content = "Não, nunca!",
  ui_story_5059_50590106_66_dialog_content = "Eu prestei total atenção no que você disse antes.",
  ui_story_5059_50590106_67_dialog_content = "Eu só queria saber como você se sente e ser seu amigo, só isso.",
  ui_story_5059_50590106_68_dialog_content = "Não tem nada a ver com os seus objetos de valor.",
  ui_story_5059_50590106_69_dialog_content = "PlayerName não é alguém interessado em riqueza.",
  ui_story_5059_50590106_70_dialog_content = "Carleen disse que PlayerName é uma alma bondosa que adora fazer amigos e está disposto a fazer sacrifícios por eles.",
  ui_story_5059_50590106_71_dialog_content = "Concordo com a opinião dela.",
  ui_story_5059_50590106_72_dialog_content = "Relaxe, o garoto pode ser um pouco lento, mas não tem um pensamento ruim naquele corpo.",
  ui_story_5059_50590106_73_dialog_content = "Bem, deixando o Odi de lado, essa criança parece ser honesta o suficiente.",
