  ui_story_5059_50590106_78_dialog_content = "Sim, joguei com todos e eles adoraram muito o seu último trabalho.",
  ui_story_5059_50590106_79_dialog_content = "Bem, é uma obra-prima, devo dizer!",
  ui_story_5059_50590106_80_dialog_content = "Gronru...",
  ui_story_5059_50590106_81_dialog_content = "Você é aquele valentão Gronru?",
  ui_story_5059_50590106_82_dialog_content = "Correto, é ela.",
  ui_story_5059_50590106_83_dialog_content = "Valentão Gronru é o apelido que eu usava nos jogos.",
