  ui_story_5059_50590106_89_dialog_content = "Nesse caso, eu te desafio para um jogo para que você possa ver o quão poderoso eu realmente sou.",
  ui_story_5059_50590107_1_dialog_content = "Uau, eu amo isso!",
  ui_story_5059_50590107_2_dialog_content = "Perdi completamente a noção do tempo jogando este jogo.",
  ui_story_5059_50590107_3_dialog_content = "Deve ser hora do jantar agora. Pelo menos é o que minha barriga me diz.",
